code_example:
#include <iostream>
#include <type_traits>

// Function template with type deduction and SFINAE to enable only integral types
template<typename T>
auto is_even(T value) -> std::enable_if_t<std::is_integral<T>::value, bool> {
    return value % 2 == 0;
}

int main() {
    std::cout << std::boolalpha;
    std::cout << "Is 4 even? " << is_even(4) << std::endl; // valid call
    // std::cout << "Is 3.14 even? " << is_even(3.14) << std::endl; // compile error if uncommented
    return 0;
}
